def solve(nums, k):
    n = len(nums)
    if n == 1:
        return nums[0]

    unique_nums = sorted(list(set(nums)))
    if k <= len(unique_nums):
        return unique_nums[k - 1]

    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    buckets = []
    cumulative_count = 0
    for num in unique_nums:
        if counts.get(num, 0) > 0:
            buckets.append((num, cumulative_count, cumulative_count + counts[num] - 1))
            cumulative_count += counts[num]

    low = 0
    high = len(buckets) - 1
    while low <= high:
        mid = (low + high) // 2
        if buckets[mid][2] >= k - 1:
            high = mid - 1
        else:
            low = mid + 1

    result_num = buckets[low][0]
    return result_num
```

