def solve(nums, k):
    n = len(nums)
    if n == 1:
        return nums[0]

    bit = [0] * (n + 1)

    def update(i, val):
        i += 1
        while i <= n:
            bit[i] += val
            i += i & -i

    def query(i):
        i += 1
        res = 0
        while i > 0:
            res += bit[i]
            i -= i & -i
        return res

    sorted_nums = sorted(list(set(nums)))
    rank_map = {val: i for i, val in enumerate(sorted_nums)}

    for num in nums:
        update(rank_map[num], 1)

    low, high = 0, len(sorted_nums) - 1
    ans = -float('inf')

    while low <= high:
        mid = (low + high) // 2
        if query(mid) >= k:
            ans = sorted_nums[mid]
            high = mid - 1
        else:
            low = mid + 1

    return ans
