def solve(nums, k):
    n = len(nums)
    if n == 1:
        return nums[0]

    compressed = []
    for num in nums:
        if not compressed or num != compressed[-1]:
            compressed.append(num)

    compressed_n = len(compressed)
    if compressed_n == k:
        return compressed[-1]

    if k <= compressed_n:
        return compressed[k-1]

    bit_length = 0
    while (1 << bit_length) <= compressed_n:
        bit_length += 1
    bit_length -= 1

    bit_trees = [[] for _ in range(bit_length + 1)]

    def update(bit_tree, index, value):
        index += 1
        while index <= bit_length + 1:
            if not bit_tree[index - 1]:
                bit_tree[index - 1] = []

            found = False
            for i, val in enumerate(bit_tree[index - 1]):
                if val == value:
                    found = True
                    break

            if not found:
                bit_tree[index - 1].append(value)
                bit_tree[index - 1].sort()
            index += index & -index

    def query(bit_tree, index):
        index += 1
        sum_val = 0
        while index > 0:
            if bit_tree[index - 1]:
                sum_val += len(bit_tree[index - 1])
            index -= index & -index
        return sum_val

    for num in compressed:
        update(bit_trees, num, 1)

    def find_kth(k):
        left, right = 0, compressed_n - 1
        while left < right:
            mid = (left + right) // 2
            if query(bit_trees, mid) < k:
                left = mid + 1
            else:
                right = mid
        return compressed[left]

    return find_kth(k)
```

