def solve(nums, k):
    n = len(nums)
    if n == 1:
        return nums[0]

    compressed = []
    last_val = None
    for num in nums:
        if num != last_val:
            compressed.append(num)
            last_val = num

    m = len(compressed)
    if k <= m:
        return compressed[k - 1]

    # Use a sorted list of counts.
    counts = {}
    for num in nums:
        counts[num] = counts.get(num, 0) + 1

    sorted_keys = sorted(counts.keys())

    total_count = sum(counts.values())
    if k > total_count:
        return sorted(nums)[-1]

    rank = 0
    for num in sorted_keys:
        count = counts[num]
        rank += count
        if rank >= k:
            return num

    return sorted(nums)[-1]
