def solve(nums):
    n = len(nums) - 1
    bit_vector = 0
    for num in nums:
        mask = 1
        while mask <= n:
            if (bit_vector & mask) != 0:
                break
            if (bit_vector & mask) == 0 and (num & mask) != 0:
                bit_vector |= mask
                break
            mask <<= 1
        else:
            bit_vector |= mask
    for i in range(1, n + 1):
        mask = 1
        while mask <= n:
            if (bit_vector & mask) != 0:
                break
            if (bit_vector & mask) == 0 and (i & mask) != 0:
                return i
            mask <<= 1
        else:
            continue
    return -1
