def solve(grid, start, goal):
    rows = len(grid)
    cols = len(grid[0])

    if not (0 <= start[0] < rows and 0 <= start[1] < cols and grid[start[0]][start[1]] != '#'):
        return []
    if not (0 <= goal[0] < rows and 0 <= goal[1] < cols and grid[goal[0]][goal[1]] != '#'):
        return []

    if start == goal:
        return [start]

    visited = set()
    queue = [(start, [start])]

    while queue:
        (row, col), path = queue.pop(0)

        if (row, col) == goal:
            return path

        visited.add((row, col))

        neighbors = []
        if row > 0 and grid[row - 1][col] != '#' and (row - 1, col) not in visited:
            neighbors.append((row - 1, col))
        if row < rows - 1 and grid[row + 1][col] != '#' and (row + 1, col) not in visited:
            neighbors.append((row + 1, col))
        if col > 0 and grid[row][col - 1] != '#' and (row, col - 1) not in visited:
            neighbors.append((row, col - 1))
        if col < cols - 1 and grid[row][col + 1] != '#' and (row, col + 1) not in visited:
            neighbors.append((row, col + 1))

        for neighbor_row, neighbor_col in neighbors:
            queue.append(((neighbor_row, neighbor_col), path + [(neighbor_row, neighbor_col)]))

    return []
