            if nums[mid] == target:
                last = mid
                low = mid + 1
            elif nums[mid] < target:
                low = mid + 1
            else:
                high = mid - 1
        return last

    first = find_first(nums, target)
    last = find_last(nums, target)
    return [first, last]
