def solve(nums, target):
    if not nums:
        return [-1, -1]

    left = 0
    right = len(nums) - 1

    while left <= right:
        mid = (left + right) // 2

        if nums[mid] == target:
            # Find the first occurrence
            first = mid
            while first > 0 and nums[first - 1] == target:
                first -= 1

            # Find the last occurrence
            last = mid
            while last < len(nums) - 1 and nums[last + 1] == target:
                last += 1

            return [first, last]
        elif nums[mid] < target:
            left = mid + 1
        else:
            right = mid - 1

    return [-1, -1]
