from collections import defaultdict, Counter
from math import gcd

def solve(nums, k):
    counts = Counter(nums)
    freqs = list(counts.values())

    if k == 1:
        return [max(freqs)]

    if k == len(set(nums)):
       return sorted(list(set(freqs)), reverse=True)[:k]


    factors = []
    for freq in freqs:
        temp = freq
        for i in range(2, int(freq**0.5) + 1):
            while temp % i == 0:
                factors.append(i)
                temp //= i
        if temp > 1:
            factors.append(temp)

    unique_factors = sorted(list(set(factors)))


    if k == 2:

        diffs = []
        for i in range(len(unique_factors)):
            for j in range(i+1, len(unique_factors)):
                diffs.append(abs(unique_factors[i] - unique_factors[j]))

        if diffs:
            return [unique_factors[diffs.index(min(diffs))]]
        else:
            return [unique_factors[0]]




    return sorted(list(set(freqs)), reverse=True)[:k]
